1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * Rejects a create request that is missing or blank in any required field
12	 * (firstName, lastName, address, city, telephone) before {@link BuildOwner} maps the
13	 * body, reporting every offending field at once. Publishes the body for later steps so
14	 * the request is bound only here.
15	 */
16	public class ValidateOwnerFields {
17	
18	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
19	            throws MissingOwnerFieldsException {
20	        List<String> missing = new ArrayList<>();
21	        requireText(missing, "firstName", request.getFirstName());
22	        requireText(missing, "lastName", request.getLastName());
23	        // Address is checked in its normalized form, so a value that is blank only once
24	        // whitespace is trimmed and collapsed (see Addresses) is still rejected here.
25	        requireText(missing, "address", Addresses.normalize(request.getAddress()));
26	        requireText(missing, "city", request.getCity());
27	        requireText(missing, "telephone", request.getTelephone());
28	        if (!missing.isEmpty()) {
29	            throw new MissingOwnerFieldsException(missing);
30	        }
31	        validated.set(request);
32	    }
33	
34	    private static void requireText(List<String> missing, String field, String value) {
35	        if (value == null || value.isBlank()) {
36	            missing.add(field);
37	        }
38	    }
39	}
