1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * City matching: two owners are in the same city when their city names are equal, compared
7	 * case-insensitively (and ignoring surrounding/internal whitespace). Used to count how many
8	 * existing owners already live in a new owner's city.
9	 */
10	final class Cities {
11	
12	    private Cities() {
13	    }
14	
15	    /**
16	     * Whether {@code owner} lives in the given city, comparing both in their canonical
17	     * (trimmed, whitespace-collapsed, lower-cased) forms.
18	     */
19	    static boolean matches(Owner owner, String city) {
20	        return normalize(city).equals(normalize(owner.getCity()));
21	    }
22	
23	    private static String normalize(String city) {
24	        if (city == null) {
25	            return "";
26	        }
27	        return city.trim().replaceAll("\\s+", " ").toLowerCase();
28	    }
29	}
