1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	
5	/**
6	 * The pinned city-to-region table used to derive an owner's locality. Maps a small,
7	 * fixed set of cities to their canonical region string; any city not listed resolves to
8	 * {@link #UNKNOWN}.
9	 */
10	public final class CityRegion {
11	
12	    /** Locality returned for a city that is not in the table. */
13	    public static final String UNKNOWN = "UNKNOWN";
14	
15	    private static final Map<String, String> CITY_TO_REGION = Map.of(
16	        "Sydney", "NSW",
17	        "Melbourne", "VIC",
18	        "Brisbane", "QLD");
19	
20	    private CityRegion() {
21	    }
22	
23	    /**
24	     * The canonical region for the given city, or {@link #UNKNOWN} when the city is not
25	     * in the table (including a {@code null} city).
26	     */
27	    public static String localityOf(String city) {
28	        return CITY_TO_REGION.getOrDefault(city, UNKNOWN);
29	    }
30	}
