14	
15	import java.util.Collection;
16	import java.util.List;
17	
18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "displayName",
25	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
26	    @Mapping(target = "initials", expression = "java(initials(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /**
35	     * The upper-cased first letters of the first and last name, dot-separated with a
36	     * trailing dot, e.g. {@code J.S.}.
37	     */
38	    default String initials(Owner owner) {
39	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
40	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
41	    }
42	
43	    /**
44	     * The owner's membership number, formatted as {@code <customerCode>-M<YY>} where
45	     * {@code YY} is the last two digits of the registration date year, e.g.
46	     * {@code SMI-0007-M26}.
47	     */
48	    default String membershipNumber(Owner owner) {
49	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
50	        return owner.getCustomerCode() + "-M" + yy;
51	    }
52	
53	    /**
54	     * The owner's membership level from 1 to 3, as defined by {@link MembershipLevel}.
55	     */
56	    default int membershipLevel(Owner owner) {
57	        return MembershipLevel.of(owner);
58	    }
59	
60	    /**
61	     * The canonical region derived from the owner's city via the pinned city-to-region
62	     * table, or {@code UNKNOWN} when the city is not in the table.
63	     */
64	    default String locality(Owner owner) {
65	        return CityRegion.localityOf(owner.getCity());
66	    }
67	
68	    /**
69	     * How the owner prefers to be contacted: {@code EMAIL} when an email address is
70	     * present, otherwise {@code PHONE}.
71	     */
72	    default String contactPreference(Owner owner) {
73	        return ContactPreference.of(owner).name();
74	    }
75	
